import{_ as a,o as d,c as e,O as r}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"操作系统基础","description":"操作系统基础：进程与线程的本质、调度、虚拟内存与分页、文件系统、五种 IO 模型。这是 JVM 和并发编程之下的那层地基。","frontmatter":{"description":"操作系统基础：进程与线程的本质、调度、虚拟内存与分页、文件系统、五种 IO 模型。这是 JVM 和并发编程之下的那层地基。","tags":["计算机基础","操作系统","并发编程","缓存"]},"headers":[],"relativePath":"cs/操作系统基础.md","filePath":"cs/操作系统基础.md","lastUpdated":1793253475000}'),s={name:"cs/操作系统基础.md"};function n(o,t,l,i,h,p){return d(),e("div",null,t[0]||(t[0]=[r(`<h1 id="操作系统基础" tabindex="-1">操作系统基础 <a class="header-anchor" href="#操作系统基础" aria-label="Permalink to &quot;操作系统基础&quot;">​</a></h1><blockquote><p>你写的高并发、JVM、锁，全都建立在操作系统的这几个概念上。 这篇不讲 API，讲「为什么」。</p></blockquote><h2 id="一、进程-vs-线程-vs-协程" tabindex="-1">一、进程 vs 线程 vs 协程 <a class="header-anchor" href="#一、进程-vs-线程-vs-协程" aria-label="Permalink to &quot;一、进程 vs 线程 vs 协程&quot;">​</a></h2><table><thead><tr><th></th><th>进程</th><th>线程</th><th>协程</th></tr></thead><tbody><tr><td>资源</td><td><strong>资源分配的基本单位</strong>（独立地址空间）</td><td>共享进程内存</td><td>共享线程栈</td></tr><tr><td>调度</td><td>进程级调度</td><td><strong>CPU 调度的基本单位</strong></td><td>用户态调度（无需内核）</td></tr><tr><td>开销</td><td>创建销毁重</td><td>较轻</td><td><strong>极轻</strong>（纳秒级切换）</td></tr><tr><td>隔离</td><td>强（一个进程崩不影响别人）</td><td>弱（共享内存，一个崩可能全崩）</td><td>弱</td></tr></tbody></table><p><strong>一句话</strong>：进程是「有自己房子的人」，线程是「房子里的人」，协程是「人手里同时做的几件事」。</p><p><strong>为什么线程切换比进程快</strong>：进程切换要换页表、清 TLB；线程切换只换栈和寄存器（共享地址空间）。</p><h2 id="二、进程状态与调度" tabindex="-1">二、进程状态与调度 <a class="header-anchor" href="#二、进程状态与调度" aria-label="Permalink to &quot;二、进程状态与调度&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">新建 → 就绪 ⇄ 运行 → 终止</span></span>
<span class="line"><span style="color:#e1e4e8;">         ↑        ↓</span></span>
<span class="line"><span style="color:#e1e4e8;">         └─ 阻塞 ←─（等待 IO / 锁）</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">新建 → 就绪 ⇄ 运行 → 终止</span></span>
<span class="line"><span style="color:#24292e;">         ↑        ↓</span></span>
<span class="line"><span style="color:#24292e;">         └─ 阻塞 ←─（等待 IO / 锁）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>调度算法</strong>：</p><table><thead><tr><th>算法</th><th>特点</th><th>问题</th></tr></thead><tbody><tr><td>FCFS（先来先服务）</td><td>简单</td><td>长任务拖死后面（护航效应）</td></tr><tr><td>SJF（短作业优先）</td><td>平均等待最短</td><td>长任务可能饿死</td></tr><tr><td>时间片轮转（RR）</td><td>公平</td><td>时间片太大=退化成 FCFS，太小=切换开销大</td></tr><tr><td>多级反馈队列</td><td>现代系统主流</td><td>复杂</td></tr></tbody></table><p><strong>上下文切换</strong>：保存当前线程的寄存器/栈，恢复下一个。这是「多线程不一定快」的根源 —— 切换本身有开销，CPU 密集任务开太多线程反而更慢。</p><h2 id="三、线程同步" tabindex="-1">三、线程同步 <a class="header-anchor" href="#三、线程同步" aria-label="Permalink to &quot;三、线程同步&quot;">​</a></h2><table><thead><tr><th>原语</th><th>作用</th></tr></thead><tbody><tr><td><strong>互斥锁（Mutex）</strong></td><td>互斥访问临界区</td></tr><tr><td><strong>信号量（Semaphore）</strong></td><td>控制同时访问的数量（可以 &gt;1）</td></tr><tr><td><strong>条件变量（CondVar）</strong></td><td>等待某个条件成立（配合锁用）</td></tr><tr><td><strong>读写锁</strong></td><td>读读并发，写写/读写互斥</td></tr></tbody></table><p><strong>死锁四条件</strong>（缺一不可）：互斥、持有并等待、不可剥夺、循环等待。<strong>破坏任意一个</strong>即可避免：</p><ul><li>一次性申请所有资源（破坏持有并等待）</li><li>按固定顺序加锁（破坏循环等待，最实用）</li><li><code>tryLock</code> 带超时（破坏不可剥夺）</li></ul><blockquote><p>Java 侧对应 <a href="/cao_note/backend/Java/06-JUC并发编程">JUC 并发编程</a>：AQS 就是这套原语在 JVM 里的实现。</p></blockquote><h2 id="四、虚拟内存与分页" tabindex="-1">四、虚拟内存与分页 <a class="header-anchor" href="#四、虚拟内存与分页" aria-label="Permalink to &quot;四、虚拟内存与分页&quot;">​</a></h2><h3 id="为什么需要虚拟内存" tabindex="-1">为什么需要虚拟内存 <a class="header-anchor" href="#为什么需要虚拟内存" aria-label="Permalink to &quot;为什么需要虚拟内存&quot;">​</a></h3><p>每个进程都以为「我独占整个内存」，其实靠操作系统把虚拟地址映射到物理地址。好处：</p><ol><li><strong>隔离</strong>：一个进程读不到别的进程的内存；</li><li><strong>省内存</strong>：不同进程共享同一份只读代码（如 libc）；</li><li><strong>简化链接</strong>：程序可以从固定地址开始加载。</li></ol><h3 id="分页与页表" tabindex="-1">分页与页表 <a class="header-anchor" href="#分页与页表" aria-label="Permalink to &quot;分页与页表&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">虚拟地址 = 页号 + 页内偏移</span></span>
<span class="line"><span style="color:#e1e4e8;">页表：页号 → 物理页框号</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">虚拟地址 = 页号 + 页内偏移</span></span>
<span class="line"><span style="color:#24292e;">页表：页号 → 物理页框号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>页</strong>：内存管理的最小单位（通常 4KB）。</li><li><strong>页表</strong>：进程级，太大 → <strong>多级页表</strong>（只给用到的地址建表）。</li><li><strong>TLB</strong>：页表的缓存（在 CPU 里），命中就不查页表 —— 这就是「进程切换慢」的原因（TLB 要刷）。</li></ul><h3 id="缺页中断" tabindex="-1">缺页中断 <a class="header-anchor" href="#缺页中断" aria-label="Permalink to &quot;缺页中断&quot;">​</a></h3><p>访问的页不在物理内存 → 触发缺页中断 → 从磁盘换入。<strong>频繁缺页 = 抖动</strong>（thrashing），说明物理内存不够或程序局部性差。</p><h2 id="五、文件系统" tabindex="-1">五、文件系统 <a class="header-anchor" href="#五、文件系统" aria-label="Permalink to &quot;五、文件系统&quot;">​</a></h2><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>inode</td><td>文件的元数据（权限、大小、数据块位置），不含文件名</td></tr><tr><td>文件名</td><td>目录项里「名字 → inode」的映射</td></tr><tr><td>软链接</td><td>指向<strong>路径</strong>（可跨文件系统，删原文件就断）</td></tr><tr><td>硬链接</td><td>指向<strong>同一个 inode</strong>（删一个名字，数据还在）</td></tr><tr><td>页缓存</td><td>文件 IO 走内核缓存，写有延迟 —— <code>fsync</code> 才落盘</td></tr></tbody></table><p><strong>为什么 <code>rm</code> 一个正在被进程打开的文件，磁盘空间不释放</strong>：文件被打开时，inode 被进程引用，要等进程关闭才真正删除。</p><h2 id="六、五种-io-模型" tabindex="-1">六、五种 IO 模型 <a class="header-anchor" href="#六、五种-io-模型" aria-label="Permalink to &quot;六、五种 IO 模型&quot;">​</a></h2><table><thead><tr><th>模型</th><th>特点</th><th>例子</th></tr></thead><tbody><tr><td>阻塞 IO</td><td>一直等数据就绪</td><td>传统 <code>read()</code></td></tr><tr><td>非阻塞 IO</td><td>立即返回，自己轮询</td><td><code>O_NONBLOCK</code></td></tr><tr><td><strong>IO 多路复用</strong></td><td>一个线程监听多个 fd</td><td>select / poll / epoll</td></tr><tr><td>信号驱动 IO</td><td>内核发信号通知</td><td>SIGIO</td></tr><tr><td>异步 IO</td><td>内核拷完再回调</td><td>io_uring、AIO</td></tr></tbody></table><p><strong>epoll 为什么快</strong>：注册一次 + 只返回就绪的（回调通知），不像 select 每次全量拷贝并遍历。完整对比见 <a href="/cao_note/backend/Java/07-Java网络编程与NIO">Java NIO</a>。</p><h2 id="七、速查" tabindex="-1">七、速查 <a class="header-anchor" href="#七、速查" aria-label="Permalink to &quot;七、速查&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>进程线程区别</td><td>资源分配单位 vs CPU 调度单位</td></tr><tr><td>线程切换为什么快</td><td>共享地址空间，不换页表</td></tr><tr><td>死锁四条件</td><td>互斥、持有并等待、不可剥夺、循环等待</td></tr><tr><td>虚拟内存好处</td><td>隔离、共享、简化加载</td></tr><tr><td>TLB 是什么</td><td>页表缓存，miss 要查内存页表</td></tr><tr><td>缺页抖动</td><td>内存不够，频繁换入换出</td></tr><tr><td>硬链接 vs 软链接</td><td>同 inode vs 指路径</td></tr><tr><td>epoll 为什么快</td><td>注册一次 + 就绪回调</td></tr></tbody></table>`,33)]))}const g=a(s,[["render",n]]);export{b as __pageData,g as default};
